import {modules,roles,statuses,repository,seed,filtered,validateState} from './core.js';
const $=s=>document.querySelector(s), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state,storageOK=true;try{state=await repository.init()}catch(e){state=seed();storageOK=false;}
let page='library',view='grid',q='',role='',sort='name';
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
async function commit(next){if(!storageOK){toast('Zapis zablokowany: nie udało się otworzyć bazy.');return false}try{await repository.save(next);state=next;return true}catch(e){toast('Nie udało się zapisać. Poprzednia wersja bazy pozostała bez zmian.');return false}}
const price=p=>p.price!==''&&p.price!=null?Number(p.price).toLocaleString('pl-PL',{style:'currency',currency:'PLN'}):'Brak ceny';
const art=p=>`<div class="visual" style="--tone:${/^#[a-f0-9]{6}$/i.test(p.tone)?p.tone:'#e8e3da'}"><span class="demo">${p.demo?'PRZYKŁAD FIKCYJNY':p.photoDataUrl?'':'BRAK ZDJĘCIA'}</span>${p.photoDataUrl?`<img class="product-photo" src="${p.photoDataUrl}" alt="Zdjęcie produktu ${esc(p.name)}">`:`<div class="bottle">blisko.skin<em>${esc(p.category)}</em></div>`}</div>`;
function shell(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#crumb').textContent={library:'Biblioteka',modules:'Moje moduły',architecture:'Koncepcja projektu'}[page];if(page==='library')library();if(page==='modules')modulePage();if(page==='architecture')architecture()}
function library(){$('#content').innerHTML=`<div class="title"><div><span class="eyebrow">Twoja przestrzeń wiedzy</span><h1>Biblioteka kosmetyków</h1><p class="subtitle">Poznaj formułę. Zapisz doświadczenie. Dobierz świadomie.</p></div><button class="primary" id="add" ${storageOK?'':'disabled'}>＋ Dodaj kosmetyk</button></div><div class="notice">Prototyp do oceny wyglądu. Produkty DEMO są fikcyjne i nie stanowią rekomendacji. ${storageOK?'Zmiany zapisują się tylko w tej przeglądarce — pobieraj kopie danych.':'Błąd odczytu danych — zapis został zablokowany, aby chronić poprzednią bazę.'}</div><div class="toolbar"><input class="search" id="search" aria-label="Szukaj kosmetyku" placeholder="⌕  Szukaj nazwy, marki lub składnika…" value="${esc(q)}"><div class="views"><button id="grid" class="${view==='grid'?'active':''}">▦ Galeria</button><button id="table" class="${view==='table'?'active':''}">☷ Tabela</button></div><button id="export" ${storageOK?'':'disabled'}>↓ Eksport</button><button id="import">↑ Przywróć kopię</button><input id="backupFile" type="file" accept="application/json,.json" hidden></div><div class="filters">${['',...roles].map(r=>`<button data-role="${esc(r)}" class="${r===role?'active':''}">${r||'Wszystkie produkty'}</button>`).join('')}</div><div class="results"><span id="count"></span><label>Sortuj <select id="sort"><option value="name">Nazwa A–Z</option><option value="recent">Ostatnio zmienione</option></select></label></div><div id="products"></div>`;$('#sort').value=sort;$('#search').oninput=e=>{q=e.target.value;results()};$('#sort').onchange=e=>{sort=e.target.value;results()};$('#add').onclick=()=>edit();$('#grid').onclick=()=>{view='grid';library()};$('#table').onclick=()=>{view='table';library()};$('#export').onclick=exportData;$('#import').onclick=()=>$('#backupFile').click();$('#backupFile').onchange=restoreData;document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{role=b.dataset.role;library()});results()}
function results(){const ps=filtered(state.products,{q,role,sort});$('#count').textContent=`${ps.length} produktów w widoku · ${state.products.filter(p=>!p.demo).length} własnych`;$('#products').innerHTML=ps.length?(view==='grid'?`<div class="grid">${ps.map(p=>`<article class="card" tabindex="0" role="button" data-id="${esc(p.id)}" aria-label="Otwórz ${esc(p.name)}">${art(p)}<div class="card-body"><span class="brand">${esc(p.brand)}</span><h3>${esc(p.name)}</h3><div class="tags"><span class="tag">${esc(p.category)}</span><span class="tag">${esc(p.role)}</span></div>${state.enabled.includes('inci')?`<p class="note">${esc(p.actives||'Składniki do uzupełnienia')}</p>`:''}<div class="card-end"><span class="status">○ ${esc(p.status)}</span><span>${price(p)}</span></div></div></article>`).join('')}</div>`:`<div class="table-wrap"><table><thead><tr><th>Produkt</th><th>Kategoria</th><th>Rola</th><th>Status</th><th>Cena</th></tr></thead><tbody>${ps.map(p=>`<tr tabindex="0" role="button" data-id="${esc(p.id)}"><td><b>${esc(p.name)}</b><small>${esc(p.brand)} ${p.demo?'· DEMO':''}</small></td><td>${esc(p.category)}</td><td>${esc(p.role)}</td><td>${esc(p.status)}</td><td>${price(p)}</td></tr>`).join('')}</tbody></table></div>`):'<div class="empty"><h2>Jeszcze nic tutaj nie ma</h2><p>Zmień wyszukiwanie lub dodaj swój pierwszy kosmetyk.</p></div>';document.querySelectorAll('[data-id]').forEach(el=>{el.onclick=()=>detail(el.dataset.id);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();detail(el.dataset.id)}}})}
function detail(id){const p=state.products.find(p=>p.id===id);const d=$('#detail');d.innerHTML=`<button class="close" aria-label="Zamknij">×</button><span class="eyebrow">${p.demo?'Fikcyjny produkt demonstracyjny':'Karta produktu'}</span><h2>${esc(p.name)}</h2><p class="subtitle">${esc(p.brand)} · ${esc(p.category)}</p><div class="section"><span class="tag">${esc(p.role)}</span> <span class="tag">${esc(p.status)}</span><p>${price(p)}${p.volume?` · ${esc(p.volume)} ${esc(p.unit)}`:''}${Number(p.volume)>0&&p.price!==''?` · ${(Number(p.price)/Number(p.volume)*100).toFixed(2)} zł / 100 ${esc(p.unit)}`:''}</p></div>${modules.filter(m=>state.enabled.includes(m.id)).map(m=>`<section class="section"><h3>${m.name}</h3><p style="white-space:pre-wrap">${esc(p.data[m.field]||'Brak danych. Uzupełnij podczas analizy produktu.')}</p>${m.id!=='notes'?'<small>Notatka robocza · bez weryfikacji merytorycznej</small>':'<small>Twoje doświadczenie · nie jest oceną naukową</small>'}</section>`).join('')}<div class="actions"><button id="remove">Usuń produkt</button><button id="edit" class="primary">Edytuj kartę</button></div>`;d.querySelector('.close').onclick=()=>d.close();$('#edit').onclick=()=>{d.close();edit(p)};$('#remove').onclick=async()=>{if(confirm('Usunąć produkt wraz z jego notatkami?')){if(await commit({...state,products:state.products.filter(x=>x.id!==p.id)})){d.close();shell();toast('Produkt usunięty')}}};d.showModal()}
function edit(p){const d=$('#editor'),v=p||{name:'',brand:'',category:'',role:roles[0],status:statuses[0],unit:'ml',data:{}};const field=(name,label,type='text')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(v[name])}" ${['name','brand','category'].includes(name)?'required maxlength="150"':''} ${type==='number'?'min="0" step="0.01"':''}></label>`;const select=(name,label,opts)=>`<label>${label}<select name="${name}">${opts.map(o=>`<option ${v[name]===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`;d.innerHTML=`<button class="close" aria-label="Zamknij">×</button><span class="eyebrow">Twoja biblioteka</span><h2>${p?'Edytuj kosmetyk':'Dodaj kosmetyk'}</h2><form><div class="field-grid">${field('brand','Marka')}${field('name','Nazwa')}${field('category','Kategoria')}${select('role','Główna rola',roles)}${field('volume','Pojemność','number')}${select('unit','Jednostka',['ml','g'])}${field('price','Cena orientacyjna (zł)','number')}<label>Zdjęcie produktu<input name="photo" type="file" accept="image/png,image/jpeg,image/webp"></label>${select('status','Twoja ocena',statuses)}${state.enabled.includes('inci')?field('actives','Główne składniki — do weryfikacji'):''}${modules.filter(m=>state.enabled.includes(m.id)).map(m=>`<label class="wide">${m.label}<textarea name="${m.field}">${esc(v.data[m.field]||'')}</textarea></label>`).join('')}</div><p class="note">Własne wpisy pozostają robocze. Weryfikacja informacji wymaga sprawdzenia źródeł.</p><div class="actions"><button type="button" id="cancel">Anuluj</button><button class="primary">Zapisz kosmetyk</button></div></form>`;d.querySelector('.close').onclick=()=>d.close();$('#cancel').onclick=()=>d.close();d.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),next={...v,id:v.id||crypto.randomUUID(),demo:v.demo||false,data:{...v.data},updatedAt:new Date().toISOString()};for(const [k,value] of f){if(k==='photo')continue;if(modules.some(m=>m.field===k))next.data[k]=value.trim();else next[k]=value.trim()}if(!next.name||!next.brand||!next.category){toast('Uzupełnij markę, nazwę i kategorię.');return}const ps=state.products.some(x=>x.id===next.id)?state.products.map(x=>x.id===next.id?next:x):[...state.products,next];const photo=e.target.elements.photo?.files?.[0];if(photo){if(!['image/png','image/jpeg','image/webp'].includes(photo.type)){toast('Wybierz zdjęcie PNG, JPG lub WebP.');return}if(photo.size>3*1024*1024){toast('Zdjęcie może mieć maksymalnie 3 MB.');return}next.photoDataUrl=await toDataUrl(photo)}if(await commit({...state,products:ps})){d.close();shell();toast('Zapisano w bazie tej przeglądarki')}};d.showModal()}
function modulePage(){$('#content').innerHTML=`<div class="title"><div><span class="eyebrow">Przestrzeń dopasowana do Ciebie</span><h1>Moje moduły</h1><p class="subtitle">Włącz to, czego potrzebujesz. Zachowaj wszystkie informacje.</p></div></div><div class="notice">Wyłączenie modułu ukrywa jego sekcję i pola formularza. Zapisane dane pozostają w bazie i kopii zapasowej.</div><div class="module"><div><h3>Biblioteka i zapis danych</h3><p>Wspólny fundament — zawsze aktywny.</p></div><span class="pill">Core</span></div>${modules.map(m=>`<div class="module"><div><h3>${m.name}</h3><p>${m.desc}</p></div><label><input class="toggle" type="checkbox" data-module="${m.id}" ${state.enabled.includes(m.id)?'checked':''} aria-label="${m.name}">Aktywny</label></div>`).join('')}<p class="note">Na kolejne etapy: bezpieczeństwo, stosowanie, ceny, porównywarka, alternatywy, beauty plany i AI. Przełączniki tutaj demonstrują sekcje karty, nie automatyczną analizę.</p>`;document.querySelectorAll('[data-module]').forEach(b=>b.onchange=async()=>{const enabled=b.checked?[...state.enabled,b.dataset.module]:state.enabled.filter(x=>x!==b.dataset.module);if(!await commit({...state,enabled}))b.checked=!b.checked})}
function toDataUrl(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.readAsDataURL(file)})}
function exportData(){const backup={format:'blisko.skin.backup',version:1,exportedAt:new Date().toISOString(),state};const url=URL.createObjectURL(new Blob([JSON.stringify(backup,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='blisko-skin-kopia-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Pobrano kopię danych JSON')}
async function restoreData(e){const file=e.target.files?.[0];e.target.value='';if(!file)return;try{const raw=JSON.parse(await file.text());if(raw.format!=='blisko.skin.backup'||raw.version!==1)throw Error('To nie jest obsługiwana kopia blisko.skin.');const restored=validateState(raw.state);const products=restored.products.filter(p=>!p.demo);if(!confirm(`Kopia zawiera ${products.length} własnych produktów. Zastąpi obecną bazę. Najpierw pobierz obecną kopię, jeśli chcesz zachować jej dane. Przywrócić?`))return;if(await repository.restore(restored)){state=restored;shell();toast('Przywrócono kopię danych')}}catch(err){toast(err.message||'Nie udało się odczytać kopii. Bieżąca baza pozostała bez zmian.')}}
function architecture(){$('#content').innerHTML=`<div class="architecture"><div class="title"><div><span class="eyebrow">Etap I · fundament</span><h1>Jedna baza. Niezależne moduły.</h1><p class="subtitle">Modularny monolit, który rozwija się razem z Twoją praktyką.</p></div></div><h2>Mały Core, jasno określeni właściciele danych</h2><p>Core przechowuje identyfikatory produktów, rejestr modułów, ustawienia, zapis, migracje oraz wspólne elementy interfejsu. Moduły udostępniają własne sekcje karty i filtry przez publiczny interfejs. Nie zapisują w tabelach innych modułów.</p><pre>src/
  app/                  nawigacja i składanie widoków
  core/                 rejestr, zdarzenia, repozytoria
  shared/ui/            pola, dialogi, tabele
  modules/
    catalog/            public.ts, model, repo, ui
    formulation/        public.ts, model, repo, ui
    skin-fit/           public.ts, model, repo, ui
    sensory/            public.ts, model, repo, ui
    observations/       public.ts, model, repo, ui
  storage/              adapter i migracje
  tests/                zachowanie danych i modułów</pre><h2>Komunikacja</h2><p>Wspólny <code>productId</code> łączy dane. Odczyty przechodzą przez publiczne API modułów. Zdarzenia <code>product.updated</code> i <code>module.disabled</code> odświeżają widoki. Rejestr zbiera sekcje karty tylko z aktywnych modułów. Nie potrzebujemy osobnych serwerów dla każdego bloku.</p><h2>Model danych</h2><div class="table-wrap"><table><tr><th>Rekord</th><th>Najważniejsze pola</th></tr><tr><td>Product</td><td>id, brand, name, category, volume, unit, mainRole, additionalRoles, photoId, updatedAt</td></tr><tr><td>FormulationVersion</td><td>id, productId, INCI, observedAt, sourceId, analysisVersion</td></tr><tr><td>Evidence</td><td>id, productId, fieldPath, value, origin, sourceId, verifiedAt, confidence</td></tr><tr><td>Source</td><td>id, URL, title, accessedAt, sourceType</td></tr><tr><td>SensoryObservation</td><td>productId, texture, finish[], absorption, fragrance, evidenceIds[]</td></tr><tr><td>PersonalObservation</td><td>id, productId, note, status, recordedAt</td></tr><tr><td>PriceObservation</td><td>productId, amount, currency, seller, date, packageSize</td></tr><tr><td>ModuleState</td><td>moduleId, enabled, schemaVersion</td></tr></table></div><p>Każda informacja otrzymuje pochodzenie: producent, analiza, recenzja lub własna obserwacja. Weryfikacja jest osobnym polem — źródło producenta nie oznacza automatycznie potwierdzenia. Brak danych nie oznacza odpowiedzi „nie”. Nowa receptura tworzy nową wersję zamiast nadpisywać historię.</p><h2>Technologie i trwałość</h2><p>Docelowy interfejs: React + TypeScript. Pierwsza baza na jednym komputerze: IndexedDB za adapterem repozytorium. Eksport i import z walidacją wersji od pierwszej wersji roboczej. Gdy potrzebna będzie synchronizacja między urządzeniami, dodamy serwerową bazę i kontrolę dostępu, zachowując kontrakty modułów.</p><p>Ta wersja używa HTML/CSS, modułów JavaScript i IndexedDB w przeglądarce. Zapis jest lokalny dla tej przeglądarki; wyczyszczenie danych witryny usuwa bazę. Eksportuj kopię JSON i przywracaj ją przez przycisk w bibliotece. Kopie są walidowane przed zastąpieniem obecnych danych.</p><h2>Zależności i bezpieczeństwo zmian</h2><p>Katalog wymaga Core. Pozostałe moduły odnoszą się do produktu przez identyfikator. Porównywarka będzie działać z dostępnymi polami, nawet gdy sensoryka jest wyłączona. Wyłączenie modułu nigdy nie usuwa danych. Archiwizacja produktu będzie preferowana w wersji roboczej; trwałe usunięcie musi obejmować również powiązane rekordy.</p><h2>Kolejność prac</h2><p>1. Ocena tej koncepcji → 2. Uzgodnienie wyglądu → 3. Core, katalog, trwały zapis i import/eksport → 4. Formularze INCI, dopasowania i sensoryki → 5. Porównywanie i beauty plany. AI pozostaje opcjonalne.</p><p class="note">Źródła techniczne: <a href="https://react.dev/learn/typescript" target="_blank" rel="noreferrer">React + TypeScript</a> · <a href="https://dexie.org/docs/StorageManager" target="_blank" rel="noreferrer">Dexie — trwałość danych</a></p></div>`}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;shell()});shell();
